// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address caller, uint256 finalTimestamp) public {
        vm.assume(caller != address(0));
        bound(finalTimestamp, 0, type(uint64).max);
        address keeper = c.keeper();
        vm.assume(caller != keeper);

        vm.warp(finalTimestamp);
        vm.prank(caller);
        bool ok;
        try c.executeBatchDeposit() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: non-keeper must revert (ok == false).
        // Mutant: non-keeper is allowed, so on some input ok == true.
        assertTrue(!ok);
    }
}
